// The browser side: draws the board, sends each move to the server and
// shows what it answers. The rules live on the server (tictactoe/game.py).
"use strict";

const boardEl = document.getElementById("board");
const statusEl = document.getElementById("status");
const modeEl = document.getElementById("mode");
const levelEl = document.getElementById("level");
const levelLabel = document.getElementById("level-label");
const cheatEl = document.getElementById("cheat");
const stealEl = document.getElementById("steal");
const cheatTextEl = document.getElementById("cheat-text");
const score = { X: 0, O: 0, draw: 0, help: 0 };

let state = null; // the server's last answer
let busy = false; // a move is on its way to the server
let focused = 0; // the cell that holds the board's single tab stop
let unlocked = false; // the cheat code was typed during this game
let stealMode = false; // the player is choosing one of the computer's squares
let notice = null; // a message the status line shows instead of the usual text
let keys = []; // the last keys typed, to recognise the cheat code

// The cheat code. It is shared on purpose, so it is plain here.
const CODE = [
  "ArrowUp", "ArrowUp", "ArrowDown", "ArrowDown",
  "ArrowLeft", "ArrowRight", "ArrowLeft", "ArrowRight", "b", "a",
];

const cells = Array.from({ length: 9 }, (_, i) => {
  const cell = document.createElement("button");
  cell.type = "button";
  cell.className = "cell";
  cell.addEventListener("click", () => choose(i));
  cell.addEventListener("keydown", (event) => onKey(event, i));
  cell.addEventListener("focus", () => { focused = i; });
  boardEl.appendChild(cell);
  return cell;
});

function newGame() {
  state = {
    board: Array(9).fill(""), status: "playing", winner: null, line: null, turn: "X",
    game: null, stealable: [], steal_used: false, assisted: false,
  };
  unlocked = false;
  stealMode = false;
  notice = null;
  keys = [];
  levelLabel.hidden = modeEl.value !== "computer";
  render();
}

// A square was chosen: in steal mode only a square the server listed as
// stealable does something; otherwise it is a move, as always.
function choose(cell) {
  if (!stealMode) move(cell);
  else if (state.stealable.includes(cell)) send({ steal: cell });
}

function move(cell) {
  if (state.status !== "playing" || state.board[cell]) return;
  send({ cell });
}

async function send(fields) {
  if (busy) return;
  busy = true;
  try {
    const response = await fetch("/api/move", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(request(fields)),
    });
    const answer = await response.json();
    if (!response.ok) throw new Error(answer.error || response.statusText);
    state = answer;
    notice = null;
    if ("steal" in fields && state.status === "playing") {
      notice = `You stole row ${Math.floor(fields.steal / 3) + 1}, column ${(fields.steal % 3) + 1}.`;
    }
    // a win with a steal counts only "with help", never as an X win
    if (state.assisted) score.help += 1;
    else if (state.status === "won") score[state.winner] += 1;
    if (state.status === "draw") score.draw += 1;
  } catch (error) {
    notice = `Something went wrong: ${error.message}`;
  } finally {
    busy = false;
    stealMode = false; // steal mode ends with the answer
  }
  render();
}

// The steal button: turns steal mode on (only when the server lists squares
// to steal) and moves the focus to the first of them; pressed again, cancels.
function toggleSteal() {
  if (stealMode) {
    cancelSteal();
    return;
  }
  if (busy || state.stealable.length === 0) return;
  stealMode = true;
  notice = "Steal: choose one of the computer's squares.";
  focused = Math.min(...state.stealable);
  render();
  cells[focused].focus();
}

function cancelSteal() {
  stealMode = false;
  notice = null;
  render();
  stealEl.focus();
}

// The body of a move request: the board, the mode and level, the game token
// from the last answer when there is one, and the given cell or steal.
function request(fields) {
  const body = { board: state.board, ...fields, mode: modeEl.value, level: levelEl.value };
  if (state.game) body.game = state.game;
  return body;
}

function render() {
  const winning = new Set(state.line || []);
  cells.forEach((cell, i) => {
    const mark = state.board[i];
    const stealable = stealMode && state.stealable.includes(i);
    cell.textContent = mark;
    cell.className = `cell ${mark.toLowerCase()} ${winning.has(i) ? "win" : ""} ${stealable ? "stealable" : ""}`;
    // aria-disabled, not disabled: a disabled button cannot keep the focus
    const disabled = stealMode ? !stealable : state.status !== "playing" || Boolean(mark);
    cell.setAttribute("aria-disabled", String(disabled));
    cell.tabIndex = i === focused ? 0 : -1;
    const row = Math.floor(i / 3) + 1;
    const col = (i % 3) + 1;
    const what = mark || "empty";
    const extra = `${winning.has(i) ? ", winning" : ""}${stealable ? ", can be stolen" : ""}`;
    cell.setAttribute("aria-label", `Row ${row}, column ${col}, ${what}${extra}`);
  });
  statusEl.textContent = notice || describe();
  document.getElementById("score-x").textContent = score.X;
  document.getElementById("score-o").textContent = score.O;
  document.getElementById("score-draw").textContent = score.draw;
  document.getElementById("score-help").textContent = score.help;
  cheatEl.hidden = !unlocked;
  const canSteal = state.stealable.length > 0;
  stealEl.setAttribute("aria-disabled", String(!canSteal));
  stealEl.setAttribute("aria-pressed", String(stealMode));
  if (canSteal) cheatTextEl.textContent = "Press Steal, then choose an O. Esc cancels.";
  else cheatTextEl.textContent = state.steal_used ? "Steal used" : "No O to steal yet";
}

function describe() {
  const vsComputer = modeEl.value === "computer";
  if (state.status === "won") {
    if (!vsComputer) return `${state.winner} wins!`;
    if (state.assisted) return "You won... with a little help";
    return state.winner === "X" ? "You win!" : "The computer wins.";
  }
  if (state.status === "draw") return "It's a draw.";
  if (vsComputer) return "Your turn (X)";
  return `${state.turn} to play`;
}

const STEPS = { ArrowLeft: -1, ArrowRight: 1, ArrowUp: -3, ArrowDown: 3 };

function onKey(event, i) {
  let next = null;
  if (event.key in STEPS) {
    const step = STEPS[event.key];
    const target = i + step;
    const sameRow = Math.floor(target / 3) === Math.floor(i / 3);
    if (target >= 0 && target < 9 && (Math.abs(step) === 3 || sameRow)) next = target;
  } else if (event.key === "Home") {
    next = 0;
  } else if (event.key === "End") {
    next = 8;
  } else {
    return; // Enter and Space click the button by themselves
  }
  event.preventDefault();
  if (next !== null) {
    focused = next;
    render();
    cells[next].focus();
  }
}

// Recognises the cheat code from the last keys typed anywhere on the page.
// Esc anywhere also ends steal mode.
function onPageKey(event) {
  if (event.key === "Escape" && stealMode) {
    cancelSteal();
    return;
  }
  if (event.ctrlKey || event.altKey || event.metaKey || event.repeat) return;
  if (event.target instanceof HTMLSelectElement) return; // arrows there change the game
  const key = event.key.length === 1 ? event.key.toLowerCase() : event.key;
  keys = [...keys, key].slice(-CODE.length);
  if (keys.join(" ") !== CODE.join(" ")) return;
  keys = [];
  if (unlocked || modeEl.value !== "computer" || state.status !== "playing") return;
  unlocked = true;
  // the "With help" column stays from now on, until the page is reloaded
  document.getElementById("score-help-head").hidden = false;
  document.getElementById("score-help").hidden = false;
  notice ="Cheat unlocked! Once this game, you may steal one of the computer's squares.";
  render();
}

document.addEventListener("keydown", onPageKey);
stealEl.addEventListener("click", toggleSteal);
document.getElementById("new-game").addEventListener("click", newGame);
modeEl.addEventListener("change", newGame);
levelEl.addEventListener("change", newGame);
newGame();

